        if isinstance(t, bool):
            return None
        if isinstance(t, (int, float)):
            return float(t)
        if not isinstance(t, str):
            return None
        s2 = t.strip()
        s2 = s2.replace('₺','').replace('TL','').replace('tl','').strip()
        if s2 == '':
            return None
        if '.' in s2 and ',' in s2:
            s2 = s2.replace('.','').replace(',', '.')
        elif ',' in s2:
            s2 = s2.replace(',', '.')
        elif '.' in s2:
            after_dot = s2.split('.')[-1]
            if len(after_dot) == 3 and after_dot.isdigit():
                s2 = s2.replace('.','')
        try:
            return float(s2)
        except ValueError:
            return None
    tutar_val = parse_tutar(tutar)
    if tutar_val is None:
        hatali += 1
        continue
    # tarih
    tarih_str = obj['tarih']
    if not isinstance(tarih_str, str):
        hatali += 1
        continue
    t = tarih_str.strip()
    parsed = None
    # YYYY-MM-DD
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', t)
    if m:
        y, mo, d = map(int, m.groups())
        try:
            parsed = date(y, mo, d)
        except ValueError:
            parsed = None
    # YYYY/MM/DD
    if parsed is None:
        m = re.fullmatch(r'(\d{4})/(\d{2})/(\d{2})', t)
        if m:
            y, mo, d = map(int, m.groups())
            try:
                parsed = date(y, mo, d)
            except ValueError:
                parsed = None
    # GG.AA.YYYY
    if parsed is None:
        m = re.fullmatch(r'(\d{1,2})\.(\d{1,2})\.(\d{4})', t)
        if m:
            d, mo, y = map(int, m.groups())
            try:
                parsed = date(y, mo, d)
            except ValueError:
                parsed = None
    # G Ay YYYY
    if parsed is None:
        ay_map = {'ocak':1,'şubat':2,'mart':3,'nisan':4,'mayıs':5,'haziran':6,'temmuz':7,'ağustos':8,'eylül':9,'ekim':10,'kasım':11,'aralık':12}
        m = re.fullmatch(r'(\d{1,2})\s+([A-Za-zİŞÇÖÜĞışçöüğ]+)\s+(\d{4})', t)
        if m:
            d = int(m.group(1)); ay_adı = m.group(2).lower(); y = int(m.group(3))
            mo = ay_map.get(ay_adı)
            if mo:
                try:
                    parsed = date(y, mo, d)
                except ValueError:
                    parsed = None
    if parsed is None:
        hatali += 1
        continue
    durum = str(obj['durum']).strip().lower()
    musteri = str(obj['musteri']).strip()
    records.append({
        'id': obj['id'],
        'musteri': musteri,
        'tutar': tutar_val,
        'tarih': parsed,
        'durum': durum,
    })

# son gecerli kayit baz alinir
by_id = {}
order = []
for r in records:
    if r['id'] not in by_id:
        order.append(r['id'])
    by_id[r['id']] = r

unique = [by_id[i] for i in order]
gecerli_kayit = len(unique)
iptal = [r for r in unique if r['durum'] == 'iptal']
iptal_sayisi = len(iptal)
on_iptal = [r for r in unique if r['durum'] != 'iptal']
toplam_tutar = round(sum(r['tutar'] for r in on_iptal), 2)

aylik = defaultdict(float)
for r in on_iptal:
    key = f'{r[tarih].year:04d}-{r[tarih].month:02d}'
    aylik[key] += r['tutar']
aylik = {k: round(v,2) for k,v in sorted(aylik.items())}

musteri_tutar = defaultdict(float)
for r in on_iptal:
    musteri_tutar[r['musteri']] += r['tutar']
en_cok = max(musteri_tutar, key=musteri_tutar.get) if musteri_tutar else None

ozet = {
    'gecerli_kayit': gecerli_kayit,
    'hatali_satir': hatali,
    'iptal_sayisi': iptal_sayisi,
    'toplam_tutar': toplam_tutar,
    'aylik': aylik,
    'en_cok_harcayan': en_cok
}
with open('ozet.json','w',encoding='utf-8') as f:
    json.dump(ozet, f, ensure_ascii=False, indent=2)
print(json.dumps(ozet, ensure_ascii=False, indent=2))
print('---unique records---')
for r in unique:
    print(r)
print('hatali:', hatali)

